from __future__ import print_function

import logging
import re
import time

from ute_ue.config import loggers as ta_ue_logging
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferMissingArguments

from ta_ue_plugin_android.ue.android.android_data_transfer import AndroidUeDtConfigPacker
from ta_ue_plugin_android.uepc.datatransfer.data_transfer_utils import get_ping_binary_name, get_ip_version
from ta_ue_plugin_android.uepc.ssh_manager import SshManager
from ta_ue_plugin_android.uepc.ue_manager_exceptions import NetworkUnreachableError, AllowedPacketLossReached, \
    HostNotReachableError
from ta_ue_plugin_android.uepc.utils import Utils


class AndroidDataTransferIcmp(LteDataTransfer):
    # pylint: disable=protected-access
    UE_SPECIFIC_OPTIONS = {'ping_count': 'c', 'ping_interface_ip': 'I', 'packet_size': 's'}
    PING_STATS_REGEX = {'packet_loss': r'(\d{1,})%',
                        'rtt_min': r'(\d{1,}.\d{1,})/\d{1,}.\d{1,}/\d{1,}.\d{1,}/\d{1,}.\d{1,} ms',
                        'rtt_avg': r'\d{1,}.\d{1,}/(\d{1,}.\d{1,})/\d{1,}.\d{1,}/\d{1,}.\d{1,} ms',
                        'rtt_max': r'\d{1,}.\d{1,}/\d{1,}.\d{1,}/(\d{1,}.\d{1,})/\d{1,}.\d{1,} ms',
                        'rtt_mdev': r'\d{1,}.\d{1,}/\d{1,}.\d{1,}/\d{1,}.\d{1,}/(\d{1,}.\d{1,}) ms'}
    PING_STATS_REGEX_WIN = {'packet_loss': r'(\d{1,})%', 'rtt_min': r'Minimum = (\d{1,})ms', 'rtt_max': r'Maximum = (\d{1,})ms',
                            'rtt_avg': r'Average = (\d{1,})ms'}

    def __init__(self, name, dt_definition, configuration, ue_instance, logger_name='ute_ue'):
        """
        Object responsible for managing icmp data transfer for different types of UEs.
        Currently supported classes: AndroiUe, AtCmdsUe
        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependent configuration provided by UE instance needed for data transfer operations
        :param ue_instance:
        """
        super(AndroidDataTransferIcmp, self).__init__(name, dt_definition, configuration, logger_name)
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        self.ue_instance = ue_instance
        self.logger.debug('"{}" instance of AndroidDataTransferIcmp created: '.format(self.name))
        self.dt_config = IcmpDtConfigPacker(self._dt_definition, self._configuration)
        self.ping_parameters = self._prepare_ping_parameters()
        self.result = None
        self.is_running_ = False
        self.success_started = False
        self.ssh_manager = None
        self.downlink_ssh_reader = None
        self.ping_cmd = None
        self.utils = Utils()

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self.is_running_ = True
        if self.ping_parameters['direction'] == "dl":
            self.logger.debug("Starting ping from app server to UE (DL)")
            self.ping_ue()
        else:
            self.logger.debug("Starting ping from UE to app server (UL)")
            self.ping_app_server()
        self.logger.info('Ping started with parameters: {}'.format(self.ping_parameters))
        self.success_started = True

    def ping_ue(self, interface_option_name='I', count_option_name='c', packet_size_option_name='s'):
        """
        Ping UE from app server which supports -I (interface o bind) and -c (count)  options
        :return:
        """
        ue_ip = self._get_ue_ip()
        self.ping_cmd = self._get_ping_cmd(ip_to_ping=ue_ip,
                                           ping_interface_ip=self.ping_parameters['ping_interface_ip'],
                                           interface_option_name=interface_option_name,
                                           count_option_name=count_option_name,
                                           packet_size_option_name=packet_size_option_name)
        ssh = self._create_ssh_manager_and_register_host(self.ping_parameters['app_server'])
        self.logger.debug('Triggering ping to UE {} with IP: {}.'.format(self.ue_instance.serial_number, ue_ip),
                          extra={'ue_id': self.ue_instance.serial_number})
        self.downlink_ssh_reader = ssh.run_cmd_and_get_non_blocking_reader(self.ping_cmd, self.ping_parameters['app_server']['host'])

    def ping_app_server(self):
        """Ping app server from UE"""
        self.ping_cmd = self._get_ping_cmd(ip_to_ping=self.ping_parameters['ping_host_ip'],
                                           count_option_name=self.UE_SPECIFIC_OPTIONS['ping_count'],
                                           packet_size_option_name=self.UE_SPECIFIC_OPTIONS['packet_size'])
        self.ue_instance._method_proxy('ping_app_server', self.ping_parameters['name'], self.ping_cmd)

    def _get_ue_ip(self):
        self.ue_instance._method_proxy('set_ip_interface_for_mobile_data', ip_version=self.ping_parameters['ip_version'])
        return self.ue_instance._method_proxy('get_ip')

    def _get_ping_cmd(self, ip_to_ping=None,
                      ping_interface_ip=None,
                      interface_option_name='I',
                      count_option_name='c',
                      packet_size_option_name='s',
                      interval_option_name='i'):
        self.logger.debug("Creating ping cmd.")
        ping_binary = get_ping_binary_name(self.ping_parameters['ip_version'])
        ping_options = []
        if self._get_ping_duration():
            ping_options.append('-w {}'.format(self.ping_parameters['duration']))
        else:
            ping_options.append('-{} {}'.format(count_option_name, self.ping_parameters['ping_count']))
        if self.ping_parameters['interval']:
            ping_options.append('-{} {}'.format(interval_option_name, self.ping_parameters['interval']))
        if ping_interface_ip:
            ping_options.append('-{} {}'.format(interface_option_name, ping_interface_ip))
        if self.ping_parameters['packet_size']:
            ping_options.append('-{} {}'.format(packet_size_option_name, self.ping_parameters['packet_size']))
        ping_cmd = '{} {} {}'.format(ping_binary, ' '.join(ping_options), ip_to_ping)
        self.logger.debug('Ping cmd = {}'.format(ping_cmd))
        return ping_cmd

    def await_finish(self):
        """Waits until this data transfer finish"""
        if not self.is_running() and self.result:
            self.logger.info('Ping already finished, output:\n{}'.format(self.result))
            return
        if self.ping_parameters['direction'] == "dl":
            self.result = self.utils.get_non_blocking_reader_result(self.downlink_ssh_reader, timeout=int(self.ping_parameters['timeout']))
        else:
            self.result = self.await_ping_app_server_finish()
        self.result = "\n".join(self.result)
        self.logger.debug('Ping output: {}'.format(self.result), extra={'ue_id': self.ue_instance.serial_number})
        self.logger.info('Ping finished, output:\n{}\n{}'.format(self.ping_cmd, self.result))
        self._verify_ping_output(self.result, self.ping_parameters['allowed_packet_loss'])
        self.is_running_ = False

    def await_ping_app_server_finish(self, sleep_time=1):
        """
        Wait for the end of ping until its finished (reader claimed to be finished) or the self.ping_parameters['timeout'] exceeded.
        :param sleep_time: time between checks
        :return:
        """
        end_time = time.time() + float(self.ping_parameters['timeout'])
        try:
            while time.time() <= end_time:
                finish = self.ue_instance._method_proxy('is_ping_to_app_server_finished', self.ping_parameters['name'])
                if finish:
                    break
                time.sleep(sleep_time)
        finally:
            return self.ue_instance._method_proxy('get_ping_report', self.ping_parameters['name'])

    def _raise_if_network_ureaachable(self, ping_output):
        if 'Network is unreachable' in ping_output:
            raise NetworkUnreachableError('Network is unreachable! Please check '
                                          'if UE is attached and if it has correct IP! {}'.format(ping_output))

    def _verify_ping_output(self, ping_output, allowed_packet_loss):
        self._raise_if_network_ureaachable(ping_output)
        self._verify_packet_loss(ping_output, allowed_packet_loss)

    def _verify_packet_loss(self, ping_output, allowed_packet_loss):
        packet_loss = self._husk_packet_loss_from_ping_output(ping_output)
        if packet_loss == 100:
            raise HostNotReachableError("Packet loss 100%")
        if packet_loss > int(allowed_packet_loss):
            raise AllowedPacketLossReached("Allowed packet loss reached: {}% > {}%".format(packet_loss, allowed_packet_loss))

    def _husk_packet_loss_from_ping_output(self, ping_output):
        packet_loss = self._husk_value_from_ping_output('packet_loss', ping_output)
        self.logger.info('Packet loss = {}%'.format(packet_loss))
        return int(packet_loss)

    def _husk_value_from_ping_output(self, stats_name, ping_output):
        stats_regex = self.PING_STATS_REGEX[stats_name]
        match = re.search(stats_regex, ping_output)
        if not match:
            raise ValueError('Unable to find {} in ping output:\n{}'.format(stats_name, ping_output))
        result = match.groups()
        value = result[0]
        return value

    def _prepare_ping_parameters(self):
        self.logger.debug("DT CONFIG {}".format(self.dt_config.__dict__))
        ping_count = self._get_ue_specific_ping_parameter('ping_count', 5)
        interval = self.dt_config.get_ping_parameter('interval')
        ping_parameters = dict(name=self.name,
                               ping_host_ip=self._get_ping_host_ip(self.dt_config),
                               ping_count=ping_count,
                               allowed_packet_loss=self.dt_config.get_ping_parameter('allowed_packet_loss', 100),
                               interval=interval,
                               timeout=self.dt_config.get_ping_parameter('timeout', self._get_ping_timeout(ping_count, interval)),
                               ping_interface_ip=self._get_ue_specific_ping_parameter('ping_interface_ip'),
                               buffer_size=self.dt_config.get_ping_parameter('buffer_size', None),
                               packet_size=self._get_ue_specific_ping_parameter('packet_size'))

        ping_parameters['ip_version'] = get_ip_version(ping_parameters['ping_host_ip'])
        ping_parameters.update(self.dt_config.get_config())

        return ping_parameters

    def _create_ssh_manager_and_register_host(self, app_server):
        self.logger.debug("Create ssh manager for icmp DL data transfer")
        self.ssh_manager = SshManager()
        self.ssh_manager.register(app_server['host'], app_server['user'], app_server['password'])
        return self.ssh_manager

    def _get_ping_host_ip(self, dt_config):
        ping_host_ip = dt_config.get_ping_parameter('ping_host_ip', dt_config.get_config()['app_server'].get('host'))
        if ping_host_ip:
            return ping_host_ip
        raise DataTransferMissingArguments("Please provide IP for ping. Possible entries are:\n"
                                           "- robot ping_host_ip keyword argument\n"
                                           "- ping_host_ip for specific app server\n"
                                           "- ping_host_ip at data_transfer['ping'] yaml section\n"
                                           "- host for app_server")

    def _get_ping_timeout(self, ping_count, interval, overhead=30):
        duration = self._get_ping_duration()
        if duration:
            return float(duration) + overhead
        interval = 1 if interval is None else interval
        return float(ping_count) * float(interval) + overhead

    def release_data_transfer(self):
        """Release SSH connections, ensure threads are stopped"""
        if self.ping_parameters['direction'] == 'dl':
            self.ssh_manager.close_all_ssh_connections()
            return
        self.ue_instance._method_proxy('release_icmp_data_transfer')

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        return self.is_running_

    def get_data_transfer_statistics(self):
        """
        Get ICMP data transfer statistics
        :return: list: packet loss, RTT min, RTT max, RTT avg
        """
        if not self.result:
            raise NotImplementedError("Unable to get statistics before awaiting for finished data transfer. \n "
                                      "Please use Await Data Tranfer Finish keyword first.")
        packet_loss = self._husk_value_from_ping_output('packet_loss', self.result)
        rtt_min = self._husk_value_from_ping_output('rtt_min', self.result)
        rtt_max = self._husk_value_from_ping_output('rtt_max', self.result)
        rtt_avg = self._husk_value_from_ping_output('rtt_avg', self.result)
        rtt_mdev = self._husk_value_from_ping_output('rtt_mdev', self.result)
        return [packet_loss, rtt_min, rtt_max, rtt_avg, rtt_mdev]

    def stop(self):
        """Not implemented"""
        raise NotImplementedError

    def check_data_transfer(self):
        """Not implemented"""
        raise NotImplementedError

    def reset_statistics(self):
        """Not implemented"""
        raise NotImplementedError

    def get_average_throughput(self):
        """Not implemented"""
        raise NotImplementedError

    def get_datagram_loss(self):
        """Not implemented"""
        raise NotImplementedError

    def _get_ping_duration(self):
        if self._dt_definition.is_forever_duration():
            return None
        return self._dt_definition.duration

    def _get_ue_specific_ping_parameter(self, param, default=None):
        if param not in self.UE_SPECIFIC_OPTIONS:
            self.logger.debug("This UE does not use ping parameter: {}".format(param))
            return None
        return self.dt_config.get_ping_parameter(param, default)


class IcmpDtConfigPacker(AndroidUeDtConfigPacker):
    def __init__(self, dt_definition, yaml_config):
        """Object for packing data transfer config into one dict"""
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        super(IcmpDtConfigPacker, self).__init__(dt_definition, yaml_config)

    def _pack_dt_keys(self, configuration):
        dt_allowed_keys = ['ping']
        dt_section = configuration['data_transfer']
        self._apply_allowed_keys(self.dt_config_to_uepc, dt_section, dt_allowed_keys)

    def get_ping_parameter(self, param, default=None):
        """Returns parameter value either from robot_kwargs (priority) or yaml config data_transfer['ping']"""
        param_value_robot_kwarg = self.dt_config_to_uepc['robot_kwargs'].get(param)
        if param_value_robot_kwarg:
            self.logger.debug("Using ping parametr from robot kwargs: {}".format(param))
            return param_value_robot_kwarg
        param_value_app_server = self.dt_config_to_uepc['app_server'].get(param)
        if param_value_app_server:
            self.logger.debug("Using ping parametr from app server config: {}".format(param))
            return param_value_app_server
        ping_section = self.dt_config_to_uepc.get('ping')
        if ping_section:
            self.logger.debug("Using ping parametr from 'ping' data transfer config section: {}".format(param))
            return ping_section.get(param, default)
        return default
